      ],
    );

    final roundTripped = Context.fromJson(
      jsonDecode(jsonEncode(context.toJson())) as Map<String, dynamic>,
    );
    expect(jsonEncode(roundTripped.toJson()), jsonEncode(context.toJson()));
  });
});

